let mc_deck=[],mc_round=0,mc_cycle=0,mc_score=0,mc_streak=0,mc_best=0,mc_locked=false,mc_current=null,mc_tokens=0;
const mc_qState={};
function mc_shuffle(arr){const a=arr.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function mc_buildDeck(){mc_deck=mc_shuffle(MC_SCENES);mc_cycle++;if(mc_current&&mc_deck.length>1&&mc_deck[0].id===mc_current.scene.id){[mc_deck[0],mc_deck[1]]=[mc_deck[1],mc_deck[0]];}}
function mc_pickQ(scene){let st=mc_qState[scene.id];if(!st)st=mc_qState[scene.id]={deck:[],last:-1};if(!st.deck.length){st.deck=mc_shuffle(scene.qs.map((_,i)=>i));if(st.deck.length>1&&st.deck[0]===st.last)[st.deck[0],st.deck[1]]=[st.deck[1],st.deck[0]];}const idx=st.deck.shift();st.last=idx;return scene.qs[idx];}
function mc_next(){if(typeof isMiniGameActive==='function'&&!isMiniGameActive('mall-choice'))return;if(!mc_deck.length)mc_buildDeck();const scene=mc_deck.shift();mc_current={scene,q:mc_pickQ(scene)};mc_round++;mc_locked=false;mc_render();}
function mc_esc(s){return String(s).replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}
function mc_ensureStyles(){if(document.getElementById('mc-style'))return;const s=document.createElement('style');s.id='mc-style';s.textContent=`
@keyframes mcShake{0%,100%{transform:translateX(0)}25%{transform:translateX(-7px)}50%{transform:translateX(7px)}75%{transform:translateX(-4px)}}
@keyframes mcGlow{0%,100%{box-shadow:none}50%{box-shadow:0 0 30px rgba(16,185,129,.28)}}
.mc-shake{animation:mcShake .3s ease}.mc-correct{animation:mcGlow .65s ease}
.mc-layout{display:grid;grid-template-columns:minmax(300px,410px) minmax(0,1fr);gap:14px;align-items:stretch}.mc-picwrap{position:relative;aspect-ratio:1/1;width:100%;overflow:hidden;border-radius:22px}.mc-pic{width:100%;height:100%;object-fit:cover;display:block}.mc-opts{display:grid;grid-template-columns:1fr;gap:9px;align-content:center}.mc-opt{min-height:58px;text-align:left}
@media(max-width:900px){.mc-layout{grid-template-columns:minmax(260px,350px) minmax(0,1fr);gap:10px}.mc-opt{min-height:54px}}@media(max-width:700px){.mc-layout{grid-template-columns:1fr}.mc-picwrap{max-width:430px;margin:0 auto}.mc-opts{grid-template-columns:1fr}.mc-opt{min-height:50px}}`;
document.head.appendChild(s);}
function startMallChoiceGame(){mc_ensureStyles();mc_deck=[];mc_round=0;mc_cycle=0;mc_score=0;mc_streak=0;mc_best=0;mc_locked=false;mc_current=null;mc_tokens=0;Object.keys(mc_qState).forEach(k=>delete mc_qState[k]);mc_next();}
function mc_render(){const box=document.getElementById('game-play-container');if(!box||!mc_current)return;const [question,correct,rawOptions,type,explain]=mc_current.q;const options=mc_shuffle(rawOptions);box.innerHTML=`
<div class="rounded-[28px] border-2 border-emerald-200 bg-gradient-to-b from-emerald-50/80 via-lime-50/45 to-amber-50/45 p-2.5 md:p-3"><div class="flex items-center justify-between gap-2 mb-2"><div class="flex items-center gap-2 min-w-0"><span class="px-3 py-1.5 rounded-full bg-white/90 border-emerald-200 text-emerald-700 font-black text-xs md:text-sm shrink-0">🛒 Lượt ${mc_round}</span><span class="px-2.5 py-1 rounded-full bg-emerald-100 text-emerald-700 font-black text-[10px] md:text-xs">${mc_esc(type)}</span></div><div class="flex gap-1.5 shrink-0"><span class="px-2.5 py-1.5 rounded-full bg-amber-50 border border-amber-200 text-amber-700 font-black text-xs md:text-sm">⭐ ${mc_score}</span><span class="px-2.5 py-1.5 rounded-full bg-rose-50 border border-rose-200 text-rose-600 font-black text-xs md:text-sm">🔥 x${mc_streak}</span><span class="px-2.5 py-1.5 rounded-full bg-emerald-50 text-emerald-700 border border-emerald-200 font-black text-xs md:text-sm">🧺 ${mc_tokens}</span></div></div>
<div data-minigame-question class="mb-2 px-3 py-2 rounded-2xl bg-white/90 border-emerald-200 text-center font-black text-slate-700 text-sm md:text-lg leading-snug">${mc_esc(question)}</div>
<div class="mc-layout"><div class="mc-picwrap"><img class="mc-pic" src="${mc_current.scene.image}" alt="Tranh trung tâm thương mại"></div><div class="mc-opts">${options.map((op,i)=>`<button class="mc-opt px-4 py-2.5 rounded-2xl border-2 ${['bg-white border-sky-200 hover:bg-sky-50','bg-white border-emerald-200 hover:bg-emerald-50','bg-white border-amber-200 hover:bg-amber-50','bg-white border-violet-200 hover:bg-violet-50'][i]} text-slate-700 font-extrabold text-sm md:text-[15px] leading-snug shadow-sm transition-all" data-answer="${mc_esc(op)}" onclick="mc_choose(this)">${mc_esc(op)}</button>`).join('')}<div id="mc-feedback" class="min-h-[34px] flex items-center justify-center text-center text-xs md:text-sm font-black text-emerald-700">🧺 Mỗi lựa chọn đúng sẽ thêm một “món thông minh” vào giỏ!</div></div></div></div>`;
if(typeof setMiniGameQuestionAudio==='function')setMiniGameQuestionAudio(question,0.92);if(typeof mcSpeakSafe==='function')setTimeout(()=>mcSpeakSafe(question,0.92),140);}
function mc_choose(btn){if(mc_locked||!mc_current)return;const answer=btn.dataset.answer;const correct=mc_current.q[1];const explain=mc_current.q[4]||'';if(answer===correct){mc_locked=true;mc_score+=12+Math.min(mc_streak,5)*2;mc_streak++;mc_best=Math.max(mc_best,mc_streak);mc_tokens++;btn.classList.add('bg-emerald-100','border-emerald-400','text-emerald-800','mc-correct');const fb=document.getElementById('mc-feedback');if(fb)fb.innerHTML=`🛒 Chọn rất hợp lý! <span class="ml-1">${mc_esc(explain)}</span>`;if(typeof playAudio==='function')playAudio('correct');if(typeof confetti==='function')confetti({particleCount:55,spread:70,origin:{y:.72}});if(typeof mcSpeakSafe==='function')mcSpeakSafe('Chính xác! Bé mua sắm rất thông minh.',1.0);setTimeout(mc_next,1500);}else{mc_streak=0;btn.classList.add('mc-shake','border-rose-400','bg-rose-50');setTimeout(()=>btn.classList.remove('mc-shake','border-rose-400','bg-rose-50'),360);const fb=document.getElementById('mc-feedback');if(fb)fb.textContent='🤔 Chưa phải lựa chọn tốt nhất. Bé cân nhắc nhu cầu, an toàn và tránh lãng phí nhé!';if(typeof playAudio==='function')playAudio('wrong');}}

window.startMallChoiceGame=startMallChoiceGame;window.mc_choose=mc_choose;
